"use client";

import * as React from "react";

import { useCalendarController } from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/react/daygrid";
import interactionPlugin from "@fullcalendar/react/interaction";
import listPlugin from "@fullcalendar/react/list";
import multiMonthPlugin from "@fullcalendar/react/multimonth";
import timeGridPlugin from "@fullcalendar/react/timegrid";
import { format } from "date-fns";
import { CalendarDays, ChevronLeft, ChevronRight, EllipsisVertical, Funnel, Plus, Search, XIcon } from "lucide-react";

import { EventCalendarViews } from "@/components/calendar/event-calendar-views";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ButtonGroup, ButtonGroupText } from "@/components/ui/button-group";
import { Checkbox } from "@/components/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";

import { demoEvents } from "./events-data";

const views = [
  { key: "dayGridMonth", label: "Month", currentLabel: "This month" },
  { key: "timeGridWeek", label: "Week", currentLabel: "This week" },
  { key: "timeGridDay", label: "Day", currentLabel: "Today" },
];

const calendars = [
  { key: "work", label: "Work" },
  { key: "personal", label: "Personal" },
  { key: "team", label: "Team" },
  { key: "focus", label: "Focus time" },
];

const plugins = [dayGridPlugin, timeGridPlugin, listPlugin, interactionPlugin, multiMonthPlugin];

export function Calendar() {
  const controller = useCalendarController();
  const [query, setQuery] = React.useState("");
  const [selectedCalendars, setSelectedCalendars] = React.useState<string[]>([]);
  const [title, setTitle] = React.useState(() => format(new Date(), "MMMM yyyy"));

  const viewKey = controller.view?.type ?? views[0].key;
  const currentView = views.find((view) => view.key === viewKey) ?? views[0];

  const events = React.useMemo(() => {
    const term = query.trim().toLowerCase();

    return demoEvents.filter((event) => {
      const matchesQuery = !term || event.title.toLowerCase().includes(term);
      const matchesCalendar = selectedCalendars.length === 0 || selectedCalendars.includes(event.calendar);

      return matchesQuery && matchesCalendar;
    });
  }, [query, selectedCalendars]);

  return (
    <div className="flex h-[calc(100svh-5rem)] min-h-[30rem] flex-col overflow-hidden rounded-md border bg-card text-card-foreground md:h-[calc(100svh-7rem)]">
      <div className="flex flex-wrap items-center gap-2 border-b p-4">
        <InputGroup className="h-7 w-full md:w-64">
          <InputGroupAddon align="inline-start">
            <Search aria-hidden="true" />
          </InputGroupAddon>
          <InputGroupInput
            aria-label="Search events"
            className="h-7"
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search..."
            value={query}
          />
        </InputGroup>

        <Button size="sm" variant="outline" onClick={() => controller.today()}>
          {currentView.currentLabel}
        </Button>

        <ButtonGroup>
          <Button aria-label="Previous period" size="icon-sm" variant="outline" onClick={() => controller.prev()}>
            <ChevronLeft />
          </Button>
          <ButtonGroupText className="h-7 whitespace-nowrap">
            <CalendarDays aria-hidden="true" />
            {title}
          </ButtonGroupText>
          <Button aria-label="Next period" size="icon-sm" variant="outline" onClick={() => controller.next()}>
            <ChevronRight />
          </Button>
        </ButtonGroup>

        <Popover>
          <PopoverTrigger
            render={
              <Button aria-label="Filter calendars" size="icon-sm" variant="outline">
                <Funnel />
                {selectedCalendars.length > 0 ? (
                  <Badge className="-end-1.5 -top-1.5 absolute size-4 justify-center rounded-full p-0 text-[0.625rem]">
                    {selectedCalendars.length}
                  </Badge>
                ) : null}
              </Button>
            }
          />
          <PopoverContent align="start" className="w-56 p-3">
            <div className="flex flex-col gap-3">
              <div className="font-medium text-sm">Calendars</div>
              {calendars.map((calendar) => (
                <div className="flex items-center gap-2" key={calendar.key}>
                  <Checkbox
                    checked={selectedCalendars.includes(calendar.key)}
                    id={`calendar-${calendar.key}`}
                    onCheckedChange={(checked) =>
                      setSelectedCalendars((current) =>
                        checked === true
                          ? [...current, calendar.key]
                          : current.filter((item) => item !== calendar.key),
                      )
                    }
                  />
                  <Label className="font-normal" htmlFor={`calendar-${calendar.key}`}>
                    {calendar.label}
                  </Label>
                </div>
              ))}
              <Button
                disabled={selectedCalendars.length === 0}
                size="sm"
                variant="outline"
                onClick={() => setSelectedCalendars([])}
              >
                Clear filters
              </Button>
            </div>
          </PopoverContent>
        </Popover>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button aria-label="Calendar options" size="icon-sm" variant="outline">
                <EllipsisVertical />
              </Button>
            }
          />
          <DropdownMenuContent align="start" className="w-48">
            <DropdownMenuLabel>Calendar view</DropdownMenuLabel>
            <DropdownMenuRadioGroup value={viewKey} onValueChange={(value) => controller.changeView(value)}>
              {views.map((view) => (
                <DropdownMenuRadioItem key={view.key} value={view.key}>
                  {view.label}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        <Button className="ms-auto" size="sm">
          <Plus />
          Add event
        </Button>
      </div>

      <div className="min-h-0 flex-1">
        <EventCalendarViews
          controller={controller}
          initialView={views[0].key}
          plugins={[...plugins]}
          popoverCloseContent={() => <XIcon className="size-5 text-muted-foreground group-hover:text-foreground" />}
          events={events}
          nowIndicator
          height="100%"
          expandRows
          dayMaxEvents
          scrollTime="08:00:00"
          datesSet={(info) => {
            setTitle(info.view.title);
          }}
        />
      </div>
    </div>
  );
}

