  {
    variants: {
      variant: {
        default: "bg-card shadow-sm ring-1 ring-foreground/10",
        subtle: "bg-card shadow-xs ring-1 ring-foreground/10",
        surface: "bg-card ring-1 ring-foreground/10",
        outline: "bg-transparent ring-1 ring-border",
        interactive:
          "bg-card ring-1 ring-foreground/10 transition-colors hover:bg-primary/5 hover:ring-primary/30",
        inset: "bg-muted/50 ring-1 ring-foreground/10",
      },
    },
    defaultVariants: { variant: "default" },
  }
)

function Card({
  className,
  size = "default",
  variant,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof cardVariants> & { size?: "default" | "sm" }) {
  return (
    <div
      data-slot="card"
      data-size={size}
      data-variant={variant}
      className={cn(cardVariants({ variant }), className)}
      {...props}
    />
  )
}

