  const ids = [...selectedAssetIds]
  if (!ids.length) return
  try {
    const results = await Promise.allSettled(
      ids.map((id) => filesApi.remove(id))
    )
    const failed = results.filter((result) => result.status === "rejected")
    setBulkTrashOpen(false)
